<?php $title='Banner';require '_head.php';if(isset($_GET['delete'])){$pdo->prepare('DELETE FROM banners WHERE id=?')->execute([(int)$_GET['delete']]);header('Location: banners.php');exit;}if($_SERVER['REQUEST_METHOD']==='POST'){$pdo->prepare('INSERT INTO banners(eyebrow,title,subtitle,image,button_text,button_url,sort_order,active) VALUES(?,?,?,?,?,?,0,1)')->execute([$_POST['eyebrow'],$_POST['title'],$_POST['subtitle'],$_POST['image'],$_POST['button_text'],$_POST['button_url']]);header('Location: banners.php');exit;}$rows=$pdo->query('SELECT * FROM banners ORDER BY id DESC')->fetchAll();?><h1>Banner</h1><div class="panel"><form method="post"><input name="eyebrow" placeholder="Eyebrow"><input name="title" placeholder="Judul" required><textarea name="subtitle" placeholder="Subjudul"></textarea><input name="image" placeholder="/uploads/banners/hero.jpg"><input name="button_text" placeholder="Teks tombol"><input name="button_url" placeholder="/produk.php"><button>Simpan</button></form></div><div class="panel"><?php foreach($rows as $r):?><p><?=e($r['title'])?> — <a href="?delete=<?=$r['id']?>" onclick="return confirm('Hapus?')">Hapus</a></p><?php endforeach;?></div><?php require '_foot.php';?>